#!/usr/bin/env python3
from openpyxl import load_workbook
from pathlib import Path
from collections import Counter

files = [Path('/root/Cycle_Plan.xlsx'), Path('/root/Count_Event_Log.xlsx'), Path('/root/Cycle_Template.xlsx')]

def infer_type(values):
    vals=[v for v in values if v is not None]
    if not vals:
        return 'empty'
    types=Counter(type(v).__name__ for v in vals)
    return ', '.join(f'{k}:{v}' for k,v in types.most_common())

for path in files:
    print('='*100)
    print(f'FILE: {path}')
    wb = load_workbook(path, data_only=False)
    print('Sheet names:', wb.sheetnames)
    for ws in wb.worksheets:
        print('-'*80)
        print(f'SHEET: {ws.title}')
        print(f'Dimensions: max_row={ws.max_row}, max_column={ws.max_column}')
        print('Merged cells:', [str(r) for r in ws.merged_cells.ranges])
        if ws.max_row >= 1:
            headers=[ws.cell(1,c).value for c in range(1, ws.max_column+1)]
            print('Row 1 / headers:', headers)
            for c,h in enumerate(headers, start=1):
                vals=[ws.cell(r,c).value for r in range(2, min(ws.max_row, 21)+1)]
                print(f'  Col {c} {h!r}: inferred sample types {infer_type(vals)}')
        print('Sample rows:')
        for r in range(1, min(ws.max_row, 8)+1):
            vals=[ws.cell(r,c).value for c in range(1, min(ws.max_column, 12)+1)]
            print(f'  R{r}: {vals}')
        if path.name == 'Cycle_Template.xlsx' and ws.title == 'Overview':
            print('OVERVIEW EXACT STRUCTURE DETAILS')
            print('Column widths:')
            for c in range(1, ws.max_column+1):
                letter=ws.cell(1,c).column_letter
                dim=ws.column_dimensions[letter]
                print(f'  {letter}: width={dim.width}, hidden={dim.hidden}')
            print('Row heights:')
            for r in range(1, ws.max_row+1):
                dim=ws.row_dimensions[r]
                print(f'  {r}: height={dim.height}, hidden={dim.hidden}')
            print('Cell values and style summary:')
            for r in range(1, ws.max_row+1):
                row=[]
                for c in range(1, ws.max_column+1):
                    cell=ws.cell(r,c)
                    if cell.value is not None:
                        row.append((cell.coordinate, cell.value, cell.style_id, cell.number_format, cell.font.name, cell.font.sz, cell.font.bold, cell.fill.fill_type, cell.fill.fgColor.rgb, cell.alignment.horizontal, cell.alignment.vertical))
                if row:
                    print(' ', row)
    print()
